window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-93259b864d682784"]={"versions": [{"id": "FIG-93259b864d682784", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (M2-Ebene) der AUTOSAR-Vorlage <em>Standardization Template</em> (<code>AUTOSAR_FO_TPS_StandardizationTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition der Nachverfolgbarkeit (Traceability) und Konformitätsbindung zwischen standardisierten Entwurfsvorlagen (<em>Blueprints</em>) und den daraus abgeleiteten, projektspezifischen Modellobjekten (<em>Derived Objects</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert im AUTOSAR-Methodologie- und Standardisierungs-Framework. Ermöglicht Authoring-Tools und Validatoren die automatisierte Prüfung, ob konkrete Software-Komponenten, Datentypen oder Schnittstellen den standardisierten Vorgaben (z. B. AUTOSAR-Standard-Profilen) entsprechen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>BlueprintMappingSet</code></strong></li>\n<li><strong>Basistyp:</strong> Spezialisiert <code>ARElement</code> (vollwertiges, paketierbares Metamodell-Element innerhalb eines <code>ARPackage</code>).</li>\n<li><strong>Rolle:</strong> Container für Zuordnungsvorschriften.</li>\n<li><strong>Beziehung:</strong> Besitzt per Komposition (<code>+blueprintMap 0..*</code>) beliebig viele <code>AtpBlueprintMapping</code>-Elemente.</li>\n<li><strong><code>AtpBlueprintMapping</code></strong></li>\n<li><strong>Stereotyp:</strong> Abstrakt (<code>«atpAbstract»</code>).</li>\n<li><strong>Rolle:</strong> Abstrakte generische Schablone zur Verknüpfung von Vorlage und Zielobjekt.</li>\n<li><strong>Assoziationen:</strong></li>\n<li><code>+/atpBlueprint 1</code> [Stereotyp <code>«atpAbstract, atpUriDef»</code>]: Abgeleitete Referenz auf das zugrundeliegende Blueprint-Element. <code>«atpUriDef»</code> erlaubt die referenzielle Auflösung auch über standardisierte URIs.</li>\n<li><code>+/atpBlueprintedElement 1</code> [Stereotyp <code>«atpAbstract»</code>]: Abgeleitete Referenz auf das abgeleitete Modellelement.</li>\n<li><strong><code>BlueprintMapping</code></strong></li>\n<li><strong>Typ:</strong> Konkrete Spezialisierung (<code>Generalization</code>) von <code>AtpBlueprintMapping</code>.</li>\n<li><strong>Redefinitionen:</strong></li>\n<li><code>+blueprint 1 {redefines atpBlueprint}</code>: Bindet exakt eine konkrete <code>AtpBlueprint</code>-Instanz.</li>\n<li><code>+derivedObject 1 {redefines atpBlueprintedElement}</code>: Bindet exakt eine konkrete <code>AtpBlueprintable</code>-Instanz.</li>\n<li><strong><code>AtpBlueprint</code></strong></li>\n<li><strong>Typ:</strong> Abstrakte Spezialisierung von <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert das standardisierte Vorlagen-Modellobjekt (z. B. genormter Interface- oder Port-Blueprint).</li>\n<li><strong><code>AtpBlueprintable</code></strong></li>\n<li><strong>Typ:</strong> Abstrakte Spezialisierung von <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert jedes konkrete AUTOSAR-Modellelement, das auf Basis eines Blueprints instanziiert/abgeleitet werden darf.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Strukturdiagramm der Entwurfszeit handelt, existieren keine ECU-Laufzeitpfade, Callbacks oder BSW-Zustände (keine Beteiligung von Det/Dem). Der statische Verarbeitungsablauf im Tooling gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Import/Bereitstellung:</strong> Einlesen standardisierter ARXML-Kataloge, die <code>AtpBlueprint</code>-Instanzen enthalten.</li>\n<li>*<em>Ableitung (</em>Derivation<em>):</em>* Generierung oder manuelle Modellierung eines projektspezifischen Modellelements (<code>AtpBlueprintable</code>) unter Referenzierung der Vorlage.</li>\n<li><strong>Trace-Verknüpfung:</strong> Erzeugung eines <code>BlueprintMappingSet</code> mit Unterelementen des Typs <code>BlueprintMapping</code>, die <code>blueprint</code> und <code>derivedObject</code> paarweise fixieren (1:1-Relation).</li>\n<li>*<em>Konformitätsprüfung (</em>Model Verification<em>):</em>* Conformance-Checker evaluieren anhand des Mappings, ob alle verpflichtenden Attribute und Signaturen des <code>AtpBlueprint</code> im <code>AtpBlueprintable</code> unverändert bzw. spezifikationskonform umgesetzt wurden.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- & ARXML-Ebene:</strong></li>\n<li><code>BlueprintMappingSet</code> ist ein Top-Level-<code>ARElement</code> und wird in separaten ARXML-Dateien ausgetauscht.</li>\n<li>Das Mapping verknüpft konkrete Modellentitäten (z. B. <code>SenderReceiverInterface</code>, <code>ApplicationSwComponentType</code>, <code>ImplementationDataType</code>) mit genormten AUTOSAR-Blueprints.</li>\n<li><strong>Null Overhead auf dem Target:</strong></li>\n<li><code>BlueprintMappingSet</code>, <code>AtpBlueprint</code> und <code>BlueprintMapping</code> sind reine Design-Time-Artefakte. Sie werden während des Generierungsprozesses (RTE-/BSW-Code-Generatoren) vollständig verworfen und belegen weder RAM noch Flash im Steuergerät.</li>\n<li><strong>Bedeutung für OEM/Tier-1-Schnittstellen:</strong></li>\n<li>Essentiell für automatisierte Delivery-Gates: Verhindert die unbemerkte Divergenz herstellerspezifischer Interface-Implementierungen gegenüber standardisierten AUTOSAR-Profilen.</li>\n</ul>"}, {"id": "FIG-5dae84a07b242632", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (M2-Ebene) der AUTOSAR-Vorlage <em>Standardization Template</em> (<code>AUTOSAR_FO_TPS_StandardizationTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition der Nachverfolgbarkeit (Traceability) und Konformitätsbindung zwischen standardisierten Entwurfsvorlagen (<em>Blueprints</em>) und den daraus abgeleiteten, projektspezifischen Modellobjekten (<em>Derived Objects</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert im AUTOSAR-Methodologie- und Standardisierungs-Framework. Ermöglicht Authoring-Tools und Validatoren die automatisierte Prüfung, ob konkrete Software-Komponenten, Datentypen oder Schnittstellen den standardisierten Vorgaben (z. B. AUTOSAR-Standard-Profilen) entsprechen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>BlueprintMappingSet</code></strong></li>\n<li><strong>Basistyp:</strong> Spezialisiert <code>ARElement</code> (vollwertiges, paketierbares Metamodell-Element innerhalb eines <code>ARPackage</code>).</li>\n<li><strong>Rolle:</strong> Container für Zuordnungsvorschriften.</li>\n<li><strong>Beziehung:</strong> Besitzt per Komposition (<code>+blueprintMap 0..*</code>) beliebig viele <code>AtpBlueprintMapping</code>-Elemente.</li>\n<li><strong><code>AtpBlueprintMapping</code></strong></li>\n<li><strong>Stereotyp:</strong> Abstrakt (<code>«atpAbstract»</code>).</li>\n<li><strong>Rolle:</strong> Abstrakte generische Schablone zur Verknüpfung von Vorlage und Zielobjekt.</li>\n<li><strong>Assoziationen:</strong></li>\n<li><code>+/atpBlueprint 1</code> [Stereotyp <code>«atpAbstract, atpUriDef»</code>]: Abgeleitete Referenz auf das zugrundeliegende Blueprint-Element. <code>«atpUriDef»</code> erlaubt die referenzielle Auflösung auch über standardisierte URIs.</li>\n<li><code>+/atpBlueprintedElement 1</code> [Stereotyp <code>«atpAbstract»</code>]: Abgeleitete Referenz auf das abgeleitete Modellelement.</li>\n<li><strong><code>BlueprintMapping</code></strong></li>\n<li><strong>Typ:</strong> Konkrete Spezialisierung (<code>Generalization</code>) von <code>AtpBlueprintMapping</code>.</li>\n<li><strong>Redefinitionen:</strong></li>\n<li><code>+blueprint 1 {redefines atpBlueprint}</code>: Bindet exakt eine konkrete <code>AtpBlueprint</code>-Instanz.</li>\n<li><code>+derivedObject 1 {redefines atpBlueprintedElement}</code>: Bindet exakt eine konkrete <code>AtpBlueprintable</code>-Instanz.</li>\n<li><strong><code>AtpBlueprint</code></strong></li>\n<li><strong>Typ:</strong> Abstrakte Spezialisierung von <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert das standardisierte Vorlagen-Modellobjekt (z. B. genormter Interface- oder Port-Blueprint).</li>\n<li><strong><code>AtpBlueprintable</code></strong></li>\n<li><strong>Typ:</strong> Abstrakte Spezialisierung von <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert jedes konkrete AUTOSAR-Modellelement, das auf Basis eines Blueprints instanziiert/abgeleitet werden darf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Strukturdiagramm der Entwurfszeit handelt, existieren keine ECU-Laufzeitpfade, Callbacks oder BSW-Zustände (keine Beteiligung von Det/Dem). Der statische Verarbeitungsablauf im Tooling gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Import/Bereitstellung:</strong> Einlesen standardisierter ARXML-Kataloge, die <code>AtpBlueprint</code>-Instanzen enthalten.</li>\n<li>*<em>Ableitung (</em>Derivation<em>):</em>* Generierung oder manuelle Modellierung eines projektspezifischen Modellelements (<code>AtpBlueprintable</code>) unter Referenzierung der Vorlage.</li>\n<li><strong>Trace-Verknüpfung:</strong> Erzeugung eines <code>BlueprintMappingSet</code> mit Unterelementen des Typs <code>BlueprintMapping</code>, die <code>blueprint</code> und <code>derivedObject</code> paarweise fixieren (1:1-Relation).</li>\n<li>*<em>Konformitätsprüfung (</em>Model Verification<em>):</em>* Conformance-Checker evaluieren anhand des Mappings, ob alle verpflichtenden Attribute und Signaturen des <code>AtpBlueprint</code> im <code>AtpBlueprintable</code> unverändert bzw. spezifikationskonform umgesetzt wurden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- & ARXML-Ebene:</strong></li>\n<li><code>BlueprintMappingSet</code> ist ein Top-Level-<code>ARElement</code> und wird in separaten ARXML-Dateien ausgetauscht.</li>\n<li>Das Mapping verknüpft konkrete Modellentitäten (z. B. <code>SenderReceiverInterface</code>, <code>ApplicationSwComponentType</code>, <code>ImplementationDataType</code>) mit genormten AUTOSAR-Blueprints.</li>\n<li><strong>Null Overhead auf dem Target:</strong></li>\n<li><code>BlueprintMappingSet</code>, <code>AtpBlueprint</code> und <code>BlueprintMapping</code> sind reine Design-Time-Artefakte. Sie werden während des Generierungsprozesses (RTE-/BSW-Code-Generatoren) vollständig verworfen und belegen weder RAM noch Flash im Steuergerät.</li>\n<li><strong>Bedeutung für OEM/Tier-1-Schnittstellen:</strong></li>\n<li>Essentiell für automatisierte Delivery-Gates: Verhindert die unbemerkte Divergenz herstellerspezifischer Interface-Implementierungen gegenüber standardisierten AUTOSAR-Profilen.</li>\n</ul>"}, {"id": "FIG-5639a299f10844b8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (M2-Ebene) der AUTOSAR-Vorlage <em>Standardization Template</em> (<code>AUTOSAR_FO_TPS_StandardizationTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition der Nachverfolgbarkeit (Traceability) und Konformitätsbindung zwischen standardisierten Entwurfsvorlagen (<em>Blueprints</em>) und den daraus abgeleiteten, projektspezifischen Modellobjekten (<em>Derived Objects</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert im AUTOSAR-Methodologie- und Standardisierungs-Framework. Ermöglicht Authoring-Tools und Validatoren die automatisierte Prüfung, ob konkrete Software-Komponenten, Datentypen oder Schnittstellen den standardisierten Vorgaben (z. B. AUTOSAR-Standard-Profilen) entsprechen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>BlueprintMappingSet</code></strong></li>\n<li><strong>Basistyp:</strong> Spezialisiert <code>ARElement</code> (vollwertiges, paketierbares Metamodell-Element innerhalb eines <code>ARPackage</code>).</li>\n<li><strong>Rolle:</strong> Container für Zuordnungsvorschriften.</li>\n<li><strong>Beziehung:</strong> Besitzt per Komposition mit Stereotyp <code>«atpSplitable»</code> (<code>+blueprintMap 0..*</code>) beliebig viele <code>AtpBlueprintMapping</code>-Elemente.</li>\n<li><strong><code>AtpBlueprintMapping</code></strong></li>\n<li><strong>Stereotyp:</strong> Abstrakt (<code>«atpAbstract»</code>).</li>\n<li><strong>Rolle:</strong> Abstrakte generische Schablone zur Verknüpfung von Vorlage und Zielobjekt.</li>\n<li><strong>Assoziationen:</strong></li>\n<li><code>+/atpBlueprint 1</code> [Stereotyp <code>«atpAbstract, atpUriDef»</code>]: Abgeleitete Referenz auf das zugrundeliegende Blueprint-Element. <code>«atpUriDef»</code> erlaubt die referenzielle Auflösung auch über standardisierte URIs.</li>\n<li><code>+/atpBlueprintedElement 1</code> [Stereotyp <code>«atpAbstract»</code>]: Abgeleitete Referenz auf das abgeleitete Modellelement.</li>\n<li><strong><code>BlueprintMapping</code></strong></li>\n<li><strong>Typ:</strong> Konkrete Spezialisierung (<code>Generalization</code>) von <code>AtpBlueprintMapping</code>.</li>\n<li><strong>Redefinitionen & Stereotypen:</strong></li>\n<li><code>+blueprint 1 {redefines atpBlueprint}</code> [Stereotyp <code>«atpIdentityContributor»</code>]: Bindet exakt eine konkrete <code>AtpBlueprint</code>-Instanz und fließt in die Identitätsbestimmung des Mappings ein.</li>\n<li><code>+derivedObject 1 {redefines atpBlueprintedElement}</code> [Stereotyp <code>«atpIdentityContributor»</code>]: Bindet exakt eine konkrete <code>AtpBlueprintable</code>-Instanz und fließt in die Identitätsbestimmung des Mappings ein.</li>\n<li><strong><code>AtpBlueprint</code></strong></li>\n<li><strong>Typ:</strong> Abstrakte Spezialisierung von <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert das standardisierte Vorlagen-Modellobjekt (z. B. genormter Interface- oder Port-Blueprint).</li>\n<li><strong><code>AtpBlueprintable</code></strong></li>\n<li><strong>Typ:</strong> Abstrakte Spezialisierung von <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert jedes konkrete AUTOSAR-Modellelement, das auf Basis eines Blueprints instanziiert/abgeleitet werden darf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Strukturdiagramm der Entwurfszeit handelt, existieren keine ECU-Laufzeitpfade, Callbacks oder BSW-Zustände (keine Beteiligung von Det/Dem). Der statische Verarbeitungsablauf im Tooling gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Import/Bereitstellung:</strong> Einlesen standardisierter ARXML-Kataloge, die <code>AtpBlueprint</code>-Instanzen enthalten.</li>\n<li>*<em>Ableitung (</em>Derivation<em>):</em>* Generierung oder manuelle Modellierung eines projektspezifischen Modellelements (<code>AtpBlueprintable</code>) unter Referenzierung der Vorlage.</li>\n<li><strong>Trace-Verknüpfung:</strong> Erzeugung eines <code>BlueprintMappingSet</code> mit Unterelementen des Typs <code>BlueprintMapping</code>, die <code>blueprint</code> und <code>derivedObject</code> paarweise fixieren (1:1-Relation).</li>\n<li>*<em>Konformitätsprüfung (</em>Model Verification<em>):</em>* Conformance-Checker evaluieren anhand des Mappings, ob alle verpflichtenden Attribute und Signaturen des <code>AtpBlueprint</code> im <code>AtpBlueprintable</code> unverändert bzw. spezifikationskonform umgesetzt wurden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Semantik:</strong> Die Redefinitionen <code>{redefines atpBlueprint}</code> und <code>{redefines atpBlueprintedElement}</code> in <code>BlueprintMapping</code> engen die abstrakten Assoziationen des Supertyps typisiert auf <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> mit Multiplizität 1 ein. Beide Rollen tragen den Stereotyp <code>«atpIdentityContributor»</code> und definieren damit gemeinsam die eindeutige Identität eines Mappings in splitbaren Modellen.</li>\n<li><strong>Modell-Splitting:</strong> Die Komposition <code>blueprintMap</code> ist mit <code>«atpSplitable»</code> versehen, wodurch die Zuordnungen eines <code>BlueprintMappingSet</code> über mehrere physische ARXML-Dateien bzw. Teilmodelle verteilt werden können.</li>\n<li><strong>Traceability & URI-Auflösung:</strong> Durch <code>«atpUriDef»</code> an <code>+/atpBlueprint</code> können Blueprints auch extern über standardisierte URIs referenziert werden, ohne dass die Vorlage zwingend physisch im selben Modellpaket vorliegen muss.</li>\n<li><strong>Modellierungsregeln:</strong> Ein <code>BlueprintMappingSet</code> dient als Paketierungsgrenze (<code>ARElement</code>), um Zuordnungen unabhängig von den eigentlichen Softwarekomponenten- oder Typdefinitionen versionieren und austauschen zu können.</li>\n</ul>"}], "trans": [{"from": "FIG-93259b864d682784", "to": "FIG-5dae84a07b242632", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5dae84a07b242632", "to": "FIG-5639a299f10844b8", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>BlueprintMappingSet.blueprintMap</code>: Ergänzung des Stereotyps <code>«atpSplitable»</code>.</li>\n<li><code>BlueprintMapping.blueprint</code>: Ergänzung des Stereotyps <code>«atpIdentityContributor»</code>.</li>\n<li><code>BlueprintMapping.derivedObject</code>: Ergänzung des Stereotyps <code>«atpIdentityContributor»</code>.</li>\n</ul>"}]};
